sited.script:

    function list_parse(url, html) {
        const $ = cheerio.load(html);
        var list = [];
        $('.row a.comicpic_col6, .row a[title]').each(function(index) {
            var $$ = cheerio.load($(this).html());
			list.push({
				name: gbk2big5.traditionalized($$('.comicpic_col6_name, .cat2_list_name').text().trim()),
				logo: 'https://www.8comic.com' + $$('img').attr('src'),
				url: "https://www.8comic.com" + $(this).attr('href')
			});
        });
        return JSON.stringify(list);
    }

    function book_parse(url, html) {
        const $ = cheerio.load(html.replace(/<script>.*?<\/script>/g,""));
        const sections = [];
        $("#rp_tb_comic_0 a.eps_a").each(function(){
            const sectionName = $(this).text().trim();
            const sectionUrl = $(this).attr("onclick").match(/'(.*)'/)[1];
            if (sectionName && sectionUrl) {
                sections.push({
                    name: gbk2big5.traditionalized(sectionName),
                    url: "https://articles.onemoreplace.tw/online/new-"+sectionUrl.replace("-",".html?ch=")
                });
            }
        });
        const book = {
            name: gbk2big5.traditionalized($(".h2").text().trim()),
            logo: 'https://www.8comic.com' + $(".item-cover img").attr("src"),
			intro: gbk2big5.traditionalized($(".item_info_detail").text().trim()),
			author: gbk2big5.traditionalized($(".item-info-author").text().trim()),
			updateTime: gbk2big5.traditionalized("更新時間："+$(".item-info-date").text().trim()),
            sections: sections
        };
        return JSON.stringify(book);
    }

    function section_parse(url, html) {
        // --- 函數開始日誌 ---
        console.log("section_parse: Function started.");
        console.log("section_parse: Input URL:", url);
        // console.log("section_parse: Input HTML length:", html.length); // 避免輸出過長的HTML

        const $ = cheerio.load(html);
        console.log("section_parse: Cheerio loaded HTML.");
        const scriptContent = $('script[language="javascript"]').text();

        // --- 腳本內容檢查日誌 ---
        console.log("section_parse: Extracted scriptContent length:", scriptContent.length);

        if (!scriptContent || scriptContent.length < 10) {
            console.warn("section_parse: scriptContent is empty or too short. Returning empty data.");
            return JSON.stringify({ type: "article", data: [] });
        }

        // --- 內部輔助函數 (沒有邏輯變動，僅保留) ---
        function lc(l){
            if(l.length!=2 ) return l;
            var az="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
            var a=l.substring(0,1);
            var b=l.substring(1,2);
            if(a=="Z") return 8000+az.indexOf(b);
            else return az.indexOf(a)*52+az.indexOf(b);
        }
        function unescape_func(encoded_str){
            var decoded_str = '';
            if (!encoded_str) return '';
            for(var i=0;i<encoded_str.length/2;i++){
                decoded_str+='%'+encoded_str.substring(i*2,i*2+2);
            }
            return unescape(decoded_str);
        }
        function substring_func(str, start, length){
             return (str+'').substring(start, start + (length == null ? 40 : length));
        }
        function nn(n){
            return n<10?'00'+n:n<100?'0'+n:n;
        }
        function mm(p){
            return (parseInt((p-1)/10)%10)+(((p-1)%10)*3);
        }

        // --- 變數初始化日誌 ---
        let decode_url_part_cache = {};
        let main_encoded_str = '';
        console.log("section_parse: Caches and main_encoded_str initialized.");

        function decode_url_part(index, main_str){
            console.log(`decode_url_part: Called for index ${index}.`);
            if(decode_url_part_cache[index]) {
                console.log(`decode_url_part: Returning cached result for index ${index}.`);
                return decode_url_part_cache[index];
            }
            if (!main_str || main_str.length < 47 + index * 6 + 6) {
                console.warn(`decode_url_part: main_str too short for index ${index}. Length: ${main_str ? main_str.length : 0}.`);
                return '';
            }
            const start = main_str.length - 47 - index * 6;
            const end = main_str.length - 47 - index * 6 + 6;
            console.log(`decode_url_part: Calculating substring from ${start} to ${end}.`);
            const result = unescape_func(main_str.substring(start, end));
            console.log(`decode_url_part: Index ${index} result: ${result}`);
            decode_url_part_cache[index] = result;
            return result;
        }

        let num_val_49, num_val_48, num_val_46;
        let v49_name, v48_name, v46_name;
        let base_lookup = {};
        let formula_cache = {};

        // --- 動態常數提取區塊 ---
        try {
            console.log("section_parse: Starting dynamic constant extraction.");

            const v49_regex_pattern = /i\s*\*\s*\(\s*([a-zA-Z0-9_]+)\s*-\s*2\s*\)/;
            const v49_match = scriptContent.match(v49_regex_pattern);
            if (!v49_match) throw new Error("v49 match failed");
            v49_name = v49_match[1];
            console.log("section_parse: v49_name found:", v49_name);

            const v49_val_regex = new RegExp("var\\s+" + v49_name + "\\s*=\\s*([0-9]+);");
            const v49_val_match = scriptContent.match(v49_val_regex);
            if (!v49_val_match) throw new Error("v49 value match failed");
            num_val_49 = parseInt(v49_val_match[1]);
            base_lookup[v49_name + "-2"] = (i) => i * (num_val_49 - 2);
            console.log("section_parse: v49_name:", v49_name, "num_val_49:", num_val_49);

            const v48_regex_pattern = /i\s*\*\s*\(\s*([a-zA-Z0-9_]+)\s*-\s*1\s*\)/;
            const v48_match = scriptContent.match(v48_regex_pattern);
            if (!v48_match) throw new Error("v48 match failed");
            v48_name = v48_match[1];
            console.log("section_parse: v48_name found:", v48_name);

            const v48_val_regex = new RegExp("var\\s+" + v48_name + "\\s*=\\s*([0-9]+);");
            const v48_val_match = scriptContent.match(v48_val_regex);
            if (!v48_val_match) throw new Error("v48 value match failed");
            num_val_48 = parseInt(v48_val_match[1]);
            base_lookup[v48_name + "-1"] = (i) => i * (num_val_48 - 1);
            console.log("section_parse: v48_name:", v48_name, "num_val_48:", num_val_48);

            const v46_regex_pattern = /i\s*\*\s*\(\s*([a-zA-Z0-9_]+)\s*\+\s*1\s*\)/;
            const v46_match = scriptContent.match(v46_regex_pattern);
            if (!v46_match) throw new Error("v46 match failed");
            v46_name = v46_match[1];
            console.log("section_parse: v46_name found:", v46_name);

            const v46_val_regex = new RegExp("var\\s+" + v46_name + "\\s*=\\s*([0-9]+);");
            const v46_val_match = scriptContent.match(v46_val_regex);
            if (!v46_val_match) throw new Error("v46 value match failed");
            num_val_46 = parseInt(v46_val_match[1]);
            base_lookup[v46_name + "+1"] = (i) => i * (num_val_46 + 1);
            console.log("section_parse: v46_name:", v46_name, "num_val_46:", num_val_46);
            console.log("section_parse: Dynamic constants extraction successful.");

        } catch (e) {
            console.error("Error extracting dynamic constants:", e); // 保持錯誤日誌
            return JSON.stringify({ type: "article", data: [] });
        }

        // --- get_formula 函數日誌 ---
        function get_formula(var_name) {
            console.log(`get_formula: Searching for formula for variable: ${var_name}`);
            if (formula_cache[var_name]) {
                console.log(`get_formula: Returning cached formula for ${var_name}.`);
                return formula_cache[var_name];
            }

            const regex_pattern = "var\\s+" + var_name + "\\s*=\\s*lc\\(.*?i\\s*\\*\\s*\\((.+?)\\)\\s*\\+\\s*([0-9]+)(?:,([0-9]+))?.*?\\);";
            const regex = new RegExp(regex_pattern);
            const match = scriptContent.match(regex);

            if (!match) {
                console.warn(`get_formula: No match found for variable ${var_name}.`);
                return null;
            }

            const base_str = match[1].replace(/\s/g, '');
            const base_func = base_lookup[base_str];
            const offset = parseInt(match[2]);
            const length = match[3] !== undefined ? parseInt(match[3]) : null;

            console.log(`get_formula: Match found for ${var_name}. Base Str: ${base_str}, Offset: ${offset}, Length: ${length}.`);

            if (!base_func) {
                console.error(`get_formula: Base function for ${base_str} not found in base_lookup.`);
                return null;
            }

            const formula = { base: base_func, offset: offset, length: length };
            formula_cache[var_name] = formula;
            console.log(`get_formula: Formula cached for ${var_name}.`);
            return formula;
        }

        // --- 主要邏輯區塊 ---
        try {
            console.log("section_parse: Starting main parsing logic.");

            // 提取變數名稱
            let match;
            const var_names_to_find = [
                { name: "main_encoded_str_name", regex: /\(([a-zA-Z0-9_]+)\.substring\(([a-zA-Z0-9_]+)\.length/ },
                { name: "ch_var_name", regex: /if\s*\(\s*([a-zA-Z0-9_]+)\s*==\s*ch/ },
                { name: "ps_var_name", regex: /\)\s*;\s*ps\s*=\s*([a-zA-Z0-9_]+)\s*;\s*if\s*\(/ },
                { name: "part_var_name", regex: /part\s*==\s*([a-zA-Z0-9_]+)\)/ },
                { name: "pg9_var_name", regex: /\(\s*([a-zA-Z0-9_]+)\s*,\s*0\s*,\s*1\s*\)/ },
                { name: "k66_var_name", regex: /\(\s*([a-zA-Z0-9_]+)\s*,\s*mm\(j\)\s*,\s*3\s*\)/ }
            ];

            const extracted_vars = {};
            for (const { name, regex } of var_names_to_find) {
                match = scriptContent.match(regex);
                if (!match) throw new Error(`${name} match failed`);
                extracted_vars[name] = match[1];
                console.log(`section_parse: Extracted ${name}: ${match[1]}`);
            }

            const { main_encoded_str_name, ch_var_name, ps_var_name, part_var_name, pg9_var_name, k66_var_name } = extracted_vars;

            // 提取 main_encoded_str
            const str_matches_regex = new RegExp("var\\s+"+main_encoded_str_name+"\\s*=\\s*'([^']+?)';");
            const str_matches = scriptContent.match(str_matches_regex);
            let foundMainStr = false;
            if (str_matches) {
                main_encoded_str = str_matches[1];
                foundMainStr = true;
                console.log("section_parse: Found main_encoded_str. Length:", main_encoded_str.length);
            }
            if (!foundMainStr) {
                console.warn("section_parse: Main encoded string not found. Returning empty data.");
                return JSON.stringify({ type: "article", data: [] });
            }

            // 提取 chs & ti
            const chs_ti_regex = /var\s+chs=([0-9]+);var\s+ti=([0-9]+);/;
            const chs_ti_match = scriptContent.match(chs_ti_regex);
            if (!chs_ti_match) throw new Error("chs & ti match failed");
            const chs = parseInt(chs_ti_match[1]);
            const ti = chs_ti_match[2];
            console.log("section_parse: chs:", chs, "ti:", ti);

            // 提取 URL 中的 ch 和 part
            let current_ch_str = '1';
            let current_part_str = '0';
            const url_ch_regex = /ch=([0-9]+)([a-zA-Z]?)/;
            const url_ch_match = url.match(url_ch_regex);
            if (url_ch_match) {
                current_ch_str = url_ch_match[1];
                if (url_ch_match[2]) {
                    current_part_str = url_ch_match[2];
                }
                console.log("section_parse: URL match. current_ch_str:", current_ch_str, "current_part_str:", current_part_str);
            } else {
                const js_ch_regex_pattern = "if\\(ch=='')\\s*ch=([0-9]+);";
                const js_ch_regex = new RegExp(js_ch_regex_pattern);
                const js_ch_match = scriptContent.match(js_ch_regex);
                if (js_ch_match) {
                    current_ch_str = js_ch_match[1];
                    console.log("section_parse: JS fallback ch match. current_ch_str:", current_ch_str);
                } else {
                    console.warn("section_parse: Could not find ch in URL or JS fallback. Using default '1'.");
                }
            }

            // 獲取所有公式
            const ch_formula = get_formula(ch_var_name);
            const ps_formula = get_formula(ps_var_name);
            const part_formula = get_formula(part_var_name);
            const pg9_formula = get_formula(pg9_var_name);
            const k66_formula = get_formula(k66_var_name);

            if (!ch_formula || !ps_formula || !part_formula || !pg9_formula || !k66_formula) {
                console.error("section_parse: One or more formulas could not be extracted.");
                return JSON.stringify({ type: "article", data: [] });
            }
            console.log("section_parse: All necessary formulas extracted.");

            // 提取迴圈限制
            let loop_limit = 0;
            const loop_limit_regex_pattern = `for\\s*\\(\\s*var\\s+i\\s*=\\s*0\\s*;\\s*i\\s*<\\s*([0-9]+)\\s*;.*?if\\s*\\(\\s*${ch_var_name}\\s*==\\s*ch`;
            const loop_limit_regex = new RegExp(loop_limit_regex_pattern);
            const loop_limit_match = scriptContent.match(loop_limit_regex);

            if (loop_limit_match && loop_limit_match[1]) {
                loop_limit = parseInt(loop_limit_match[1]);
                console.log("section_parse: Loop limit extracted:", loop_limit);
            } else {
                console.error("Could not find loop limit! Using fallback chs:", chs); // 保持關鍵錯誤日誌
                loop_limit = chs; // Fallback
            }

            var imageList = [];
            var currentSectionIndex = -1;
            let ch_val, part_val, ps, pg9_719, k66vp831a4_part;

            console.log("section_parse: Starting section index search loop (i=0 to", loop_limit - 1, "). Target ch:", current_ch_str, "Target part:", current_part_str);

            // --- 尋找章節索引迴圈 ---
            for (var i = 0; i < loop_limit; i++){
                try {
                    // 檢查 part
                    const part_base_offset = part_formula.base(i) + part_formula.offset;
                    const part_len = part_formula.length;
                    const part_str_segment = substring_func(main_encoded_str, part_base_offset, part_len);
                    if (part_str_segment === null || part_str_segment === undefined) {
                        console.warn(`Section search loop (i=${i}): part_str_segment is null/undefined. Skipping.`);
                        continue;
                    }
                    const part_num = lc(part_str_segment);

                    // console.log(`i=${i}: part_str_segment: ${part_str_segment}, part_num: ${part_num}`); // 過於頻繁，可取消註釋除錯特定迭代

                    if (part_num == current_part_str) {
                        // 檢查 chapter
                        const ch_base_offset = ch_formula.base(i) + ch_formula.offset;
                        const ch_len = ch_formula.length;
                        const ch_str_segment = substring_func(main_encoded_str, ch_base_offset, ch_len);
                        if (ch_str_segment === null || ch_str_segment === undefined) {
                            console.warn(`Section search loop (i=${i}): ch_str_segment is null/undefined. Skipping.`);
                            continue;
                        }
                        const chapter_num = lc(ch_str_segment);

                        // console.log(`i=${i}: ch_str_segment: ${ch_str_segment}, chapter_num: ${chapter_num}`); // 過於頻繁，可取消註釋除錯特定迭代

                        if (chapter_num == current_ch_str) {
                             currentSectionIndex = i;
                             ch_val = chapter_num;
                             console.log(`section_parse: Match found at index i=${i}. Chapter: ${chapter_num}, Part: ${part_num}. Breaking loop.`);
                             break;
                        }
                    }
                } catch (loopError) {
                     console.error(`Error inside currentSectionIndex loop (i=${i}):`, loopError); // 保持錯誤日誌
                }
            }

            // --- 處理找到的章節索引 ---
            if (currentSectionIndex != -1) {
                 var i = currentSectionIndex;

                 // 提取章節相關值
                 ps = lc(substring_func(main_encoded_str, ps_formula.base(i) + ps_formula.offset, ps_formula.length));
                 pg9_719 = lc(substring_func(main_encoded_str, pg9_formula.base(i) + pg9_formula.offset, pg9_formula.length));
                 k66vp831a4_part = substring_func(main_encoded_str, k66_formula.base(i) + k66_formula.offset, k66_formula.length);
                 part_val = lc(substring_func(main_encoded_str, part_formula.base(i) + part_formula.offset, part_formula.length));

                 console.log(`section_parse: Chapter data extracted: Index=${i}, ps=${ps}, pg9_719=${pg9_719}, part_val=${part_val}, ch_val=${ch_val}.`);
                 console.log(`section_parse: k66vp831a4_part length: ${k66vp831a4_part ? k66vp831a4_part.length : 0}`);


                 // --- 圖片 URL 生成迴圈 ---
                 console.log("section_parse: Starting image URL generation loop (j=1 to", ps, ").");
                 for(var j = 1; j <= ps; j++){
                     try {
                         // 提取 URL 部份
                         const part1 = decode_url_part(4, main_encoded_str);
                         const pg9_719_str = String(pg9_719);
                         const part2 = substring_func(pg9_719_str, 0, 1);
                         const part3 = decode_url_part(3, main_encoded_str);
                         const part4 = decode_url_part(2, main_encoded_str);
                         const part5 = decode_url_part(3, main_encoded_str); // 注意：這裡 part3 和 part5 都是 decode_url_part(3)
                         const part6 = substring_func(pg9_719_str, 1, 1);
                         const part7 = ti;
                         const part8 = String(ch_val) + (String(part_val) == "0" ? "" : String(part_val));
                         const part9 = nn(j);
                         const part10 = substring_func(k66vp831a4_part, mm(j), 3);
                         const part11 = decode_url_part(1, main_encoded_str);

                         // 構建編碼 URL
                         let encodedUrl = '';
                         encodedUrl += '%2f%2f' + part1 + part2 + '%2e%38' + part3 + part4 + part5 + '%2f' + part6 + '%2f' + part7 + '%2f' + part8 + '%2f' + part9 + '%5f' + part10 + '%2e' + part11;

                         const fullImageUrl = 'https:' + unescape(encodedUrl);
                         imageList.push(fullImageUrl);

                         // console.log(`Image loop (j=${j}): Part1=${part1}, Part10=${part10}, FullURL=${fullImageUrl}`); // 過於頻繁，可取消註釋除錯特定圖片

                     } catch (loopError) {
                          console.error("Error inside image generation loop (j=" + j + "):", loopError); // 保持錯誤日誌
                     }
                 }
                 console.log(`section_parse: Image URL generation complete. Total images: ${imageList.length}.`);

            } else {
                 console.error("Cannot generate image URLs: currentSectionIndex not found."); // 保持錯誤日誌
            }

        } catch (e) {
            console.error("Error during main logic execution:", e); // 保持錯誤日誌
            console.error("Stack trace:", e.stack); // 保持錯誤日誌
            return JSON.stringify({ type: "article", data: [] });
        }

        // --- 構建最終結果 ---
        var data = imageList.map(fullImageUrl => {
            return {
                t: "image",
                d: fullImageUrl,
                referer: "https://www.8comic.com/" // 假設這是固定的
            };
        });

        console.log("section_parse: Function finished. Returning result with data length:", data.length);

        return JSON.stringify({
            type: "article",
            data: data
        });
    }
